  { w: 'breakthrough', pos: 'n.', zh: '突破；重大進展', lv: 6, ex: "Scientists made a major breakthrough in developing a cheaper treatment for cancer.", exZh: '科學家在研發更便宜的癌症療法上有了重大突破。' },
  { w: 'bribe', pos: 'n./v.', zh: '賄賂', lv: 5, ex: "The official was arrested for accepting a bribe from a construction company.", exZh: '那名官員因收受建設公司的賄賂而被捕。' },
  { w: 'brisk', pos: 'adj.', zh: '輕快的；（天氣）清新涼爽的', lv: 6, ex: "We took a brisk walk along the river to warm up on the cold morning.", exZh: '在寒冷的早晨，我們沿著河邊快步走來暖身。' },
  { w: 'browse', pos: 'v.', zh: '瀏覽；隨意翻閱', lv: 5, ex: "I like to browse in second-hand bookstores on quiet, rainy afternoons.", exZh: '我喜歡在安靜的雨天午後逛二手書店。' },
  { w: 'bulk', pos: 'n.', zh: '大量；大部分；體積', lv: 5, ex: "The bulk of the cleanup work was done by volunteers from local high schools.", exZh: '大部分的清理工作是由當地高中的志工完成的。' },
  { w: 'bureaucracy', pos: 'n.', zh: '官僚體制；繁文縟節', lv: 6, ex: "Small business owners often complain about the bureaucracy involved in getting a license.", exZh: '小企業主常抱怨申請執照時的繁瑣官僚程序。' }
